import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void kthMaior() {
        assertEquals(5, Solution.kthLargest(new int[]{3,2,1,5,6,4}, 2));
        assertEquals(6, Solution.kthLargest(new int[]{3,2,1,5,6,4}, 1));
    }

    @Test void topKDecrescente() {
        assertArrayEquals(new int[]{6,5}, Solution.topK(new int[]{3,2,1,5,6,4}, 2));
    }

    @Test void duplicatas() {
        assertEquals(2, Solution.kthLargest(new int[]{2,2,2,1}, 3));
    }

    @Test void kInvalido() {
        assertThrows(IllegalArgumentException.class, () -> Solution.kthLargest(new int[]{1}, 2));
    }
}
